const joystick = document.getElementById('joystick');
const joystickKnob = document.getElementById('joystickKnob');
let joystickId = null;

function setJoystick(e) {
  if (!game || !joystick || !joystickKnob) return;
  const rect = joystick.getBoundingClientRect();
  const cx = rect.left + rect.width / 2;
  const cy = rect.top + rect.height / 2;
  let dx = e.clientX - cx;
  let dy = e.clientY - cy;
  const max = rect.width * 0.36;
  const len = Math.hypot(dx, dy) || 1;
  if (len > max) { dx = dx / len * max; dy = dy / len * max; }
  joystickKnob.style.transform = `translate(${dx}px, ${dy}px)`;

  const nx = dx / max, ny = dy / max;
  const dead = 0.2;
  const inp = game.input;
  inp.left = nx < -dead;
  inp.right = nx > dead;
  inp.up = ny < -dead;

  inp.up = ny < -dead;
  inp.down = ny > dead;
}

function resetJoystick() {
  joystickId = null;
  if (joystickKnob) joystickKnob.style.transform = '';
  if (!game) return;
  game.input.left = game.input.right = game.input.up = game.input.down = false;
}

if (joystick) {
  joystick.addEventListener('pointerdown', (e) => {
    if (!game) return;
    audio.ensure();
    joystickId = e.pointerId;
    joystick.setPointerCapture?.(e.pointerId);
    joystick.classList.add('active');
    setJoystick(e);
    e.preventDefault();
  });
  joystick.addEventListener('pointermove', (e) => {
    if (e.pointerId !== joystickId) return;
    setJoystick(e);
    e.preventDefault();
  });
  joystick.addEventListener('pointerup', (e) => {
    if (e.pointerId !== joystickId) return;
    joystick.classList.remove('active');
    resetJoystick();
    e.preventDefault();
  });
  joystick.addEventListener('pointercancel', (e) => {
    if (e.pointerId !== joystickId) return;
    joystick.classList.remove('active');
    resetJoystick();
  });
}

