      if (stack) this._useOrEquip(stack);
    });
    if (this.el.invDetail) this.el.invDetail.addEventListener('click', (e) => {
      const btn = e.target.closest('[data-item-action]');
      if (!btn || !this.game || !this.selectedStack) return;
